import test from 'node:test';import assert from 'node:assert/strict';
import{createRun,step,observation,simulate,metrics,restore,serialize,withdrawal,HORIZON}from'./engine.js';
test('delayed observation only uses the appropriate historical level',()=>{let s=createRun({lag:3});for(let i=0;i<10;i++){s=step(s,12);assert.equal(observation(s),s.history[Math.max(0,s.tick-3)].level);if(s.tick<3)assert.equal(observation(s),50);}});
test('stock, inflow, withdrawal, overflow and unmet demand conserve quantities',()=>{for(const scenario of ['shift','wave','steady'])for(const response of [.1,.3,1])for(const lag of[0,4,12]){let s=createRun({scenario,response,lag});for(let i=0;i<HORIZON;i++){const old=s;s=step(s,i%3===0?0:i%3===1?12:5);const r=s.history.at(-1);assert.ok(Math.abs(s.level-(old.level+r.pump-r.withdrawal-r.spill+r.unmet))<1e-9);assert.ok(s.level>=0&&s.level<=100);assert.ok(s.pump>=0&&s.pump<=12);}}});
test('response lag is distinct from measurement lag',()=>{const instant=step(createRun({response:1,lag:4}),10),slow=step(createRun({response:.2,lag:4}),10);assert.equal(instant.pump,10);assert.equal(slow.pump,6);assert.equal(observation(instant),50);});
test('same disturbances allow a fair comparison while delay changes feedback decisions',()=>{const a=simulate({lag:0,gain:.8}),b=simulate({lag:8,gain:.8});assert.deepEqual(a.history.map(r=>r.withdrawal),b.history.map(r=>r.withdrawal));assert.notDeepEqual(a.history.map(r=>r.command),b.history.map(r=>r.command));assert.ok(metrics(b).meanError>metrics(a).meanError);});
test('manual replay conserves the exact controls and trajectory',()=>{let s=createRun({lag:7,response:.2,scenario:'wave'});for(let i=0;i<25;i++)s=step(s,(i*7)%13);assert.deepEqual(restore(JSON.parse(JSON.stringify(serialize(s)))),s);assert.throws(()=>restore({settings:{},commands:[99]}));});
test('invalid or completed steps leave their source intact',()=>{const s=simulate();const before=structuredClone(s);assert.throws(()=>step(s,5));assert.deepEqual(s,before);assert.throws(()=>step(createRun(),NaN));assert.equal(withdrawal(5,'shift'),5);});
